from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    separate_groups = []  # Initialize an empty list to store separate groups
    group = ""  # Initialize an empty string to store each separate group

    for char in paren_string:
        if char == "(":
            if group:
                separate_groups.append(group)
            group = "("
        elif char == ")":
            group += ")"
            separate_groups.append(group)
            group = ""

    return separate_groups

